# Grayscale antialiased font data, generated by build_font.py
# from Liberation Serif / Liberation Sans.  Coverage values are
# 0-255 grayscale (never thresholded to 1-bit).
import base64 as _b64
import json as _json
import zlib as _zlib


def _load(blob):
    return _json.loads(_zlib.decompress(_b64.b64decode(blob)).decode('utf-8'))


